1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Circle Display</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	    html, body {
14	      width: 100%;
15	      height: 100%;
16	      overflow: hidden;
17	    }
18	    body {
19	      display: flex;
20	      justify-content: center;
21	      align-items: center;
22	      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
23	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
24	    }
25	    .circle-container {
26	      cursor: pointer;
27	      transition: transform 0.3s ease;
28	    }
29	    .circle-container:hover,
30	    .circle-container:focus {
31	      transform: scale(1.05);
32	      outline: none;
33	    }
34	    .circle-container:focus-visible {
35	      outline: 3px solid rgba(255, 255, 255, 0.5);
36	      outline-offset: 8px;
37	      border-radius: 50%;
38	    }
39	    svg {
40	      width: min(400px, 80vw);
41	      height: min(400px, 80vw);
42	      filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.3));
43	      display: block;
44	      transition: filter 0.3s ease;
45	    }
46	    circle {
47	      fill: #ffffff;
48	      stroke: rgba(255, 255, 255, 0.2);
49	      stroke-width: 2;
50	      transition: fill 0.3s ease, r 0.3s ease;
51	      animation: pulse 3s ease-in-out infinite;
52	    }
53	    .circle-container:hover circle,
54	    .circle-container:focus circle {
55	      fill: #e8f4f8;
56	      r: 205;
57	    }
58	    .circle-container.active circle {
59	      fill: #ffd700;
60	      animation: pulse-active 0.6s ease-in-out;
61	    }
62	    .circle-container.active:hover circle {
63	      fill: #ffed4e;
64	    }
65	    .circle-container.active svg {
66	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
67	    }
68	    @keyframes pulse {
69	      0%, 100% { r: 200; }
70	      50% { r: 202; }
71	    }
72	    @keyframes pulse-active {
73	      0% { r: 200; }
74	      50% { r: 210; }
75	      100% { r: 200; }
76	    }
77	  </style>
78	</head>
79	<body>
80	  <button class="circle-container" id="decorative-circle" aria-label="Interactive circle, click or press space to activate">
81	    <svg viewBox="0 0 400 400" role="presentation">
82	      <circle cx="200" cy="200" r="200"/>
83	    </svg>
84	  </button>
85	
86	  <script>
87	    const circle = document.getElementById('decorative-circle');
88	
89	    circle.addEventListener('click', () => {
90	      circle.classList.toggle('active');
91	    });
92	
93	    circle.addEventListener('keydown', (e) => {
94	      if (e.key === ' ' || e.key === 'Enter') {
95	        e.preventDefault();
96	        circle.click();
97	      }
98	    });
99	  </script>
100	</body>
101	</html>
